<script setup>
import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue';
defineProps({ overview:Object, range:Object, loading:Boolean, safeAreaStyle:Object, tabs:{type:Array,default:()=>[]}, active:String }); const emit=defineEmits(['back','range','tab']); const money=(value)=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(value||0));
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Báo cáo" @back="emit('back')"/><main class="min-h-0 flex-1 overflow-y-auto pb-[var(--mds-mobile-safe-bottom)]"><div class="mds-mobile-gutter-x space-y-4 py-4"><div class="flex gap-2 overflow-x-auto"><MButton v-for="item in [['month','Tháng'],['quarter','Quý'],['year','Năm']]" :key="item[0]" :variant="range.kind===item[0]?'primary':'neutral'" :loading="loading&&range.kind===item[0]" @click="emit('range',item[0])">{{ item[1] }}</MButton></div><div class="-mx-4 flex gap-1 overflow-x-auto border-y border-[var(--mds-border-light)] px-4 py-2"><MButton v-for="tab in tabs" :key="tab.key" :variant="active===tab.key?'primary':'ghost'" class="shrink-0" @click="tab.key!==active&&emit('tab',tab.key)">{{ tab.label }}</MButton></div><p class="text-[12px] text-[var(--mds-text-secondary)]">{{ range.from }} → {{ range.to }}</p><MEmptyState v-if="!overview" title="Chưa có dữ liệu báo cáo" description="Kiểm tra khoảng thời gian hoặc quyền xem báo cáo."/><template v-else><div class="grid grid-cols-2 gap-3"><article v-for="item in [[money(overview.grandTotal),'Tổng chi'],[money(overview.spend.budget),'Ngân sách'],[`${overview.network.press}/${overview.network.people}`,'Báo chí / Nhân sự'],[`+${overview.network.newPeople}`,'Nhân sự mới']]" :key="item[1]" class="rounded-lg bg-[var(--mds-bg-page)] p-3"><strong class="text-[17px]">{{ item[0] }}</strong><p class="mt-1 text-[12px] text-[var(--mds-text-secondary)]">{{ item[1] }}</p></article></div><section class="rounded-lg bg-[var(--mds-bg-page)] p-4"><h2 class="text-[15px] font-semibold">Phân bổ chi phí</h2><dl class="mt-3 space-y-2 text-[13px]"><div class="flex justify-between gap-3"><dt>Booking ({{ overview.spend.count }})</dt><dd>{{ money(overview.spend.total) }}</dd></div><div class="flex justify-between gap-3"><dt>Sự kiện</dt><dd>{{ money(overview.events.total) }}</dd></div><div class="flex justify-between gap-3"><dt>Hội phí</dt><dd>{{ money(overview.fees.total) }}</dd></div></dl></section><section><h2 class="mb-2 text-[15px] font-semibold">Cần chăm sóc</h2><MEmptyState v-if="!overview.careRisk.length" title="Không có rủi ro chăm sóc" description="Không có đầu mối vượt ngưỡng."/><div v-else class="divide-y divide-[var(--mds-border-light)] rounded-lg bg-[var(--mds-bg-page)]"><article v-for="person in overview.careRisk" :key="person.id" class="p-3"><strong class="text-[13px]">{{ person.fullName }}</strong><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ person.orgName || 'Chưa có cơ quan' }} · {{ person.days >= 999 ? 'Chưa có tương tác' : `${person.days} ngày` }}</p></article></div></section></template></div></main></section></template>
